include!("methods.rs");
fn check(){
 for n in 0..=257 {for ax in 0..8{for ay in 0..8 {let x:Vec<_>=(0..n+ax+8).map(|i|i*19+5).collect();let y:Vec<_>=(0..n+ay+8).map(|i|i*37+10000).collect();let mut wantx=x.clone();let mut wanty=y.clone();wantx[ax..ax+n].swap_with_slice(&mut wanty[ay..ay+n]);for m in 1..=3{let mut a=x.clone();let mut b=y.clone();match m{1=>chunks2(&mut a[ax..ax+n],&mut b[ay..ay+n]),2=>vec128(&mut a[ax..ax+n],&mut b[ay..ay+n]),_=>scalar(&mut a[ax..ax+n],&mut b[ay..ay+n])};assert_eq!(a,wantx);assert_eq!(b,wanty);}}}}
 for skip0 in 0..8{let mut base_a=std::array::from_fn::<_,30,_>(|i|i);let mut base_b=std::array::from_fn::<_,30,_>(|i|i+30);let mut s=skip0;for _ in 0..3{original(&mut base_a,&mut base_b,&mut s);}for m in 1..=3{let mut a=std::array::from_fn::<_,30,_>(|i|i);let mut b=std::array::from_fn::<_,30,_>(|i|i+30);let mut skip=skip0;for _ in 0..3{match m{1=>{chunk_batch(&mut a,&mut b,&mut skip);},2=>{vec_batch(&mut a,&mut b,&mut skip);},_=>{scalar_batch(&mut a,&mut b,&mut skip);}}}assert_eq!((a,b,skip),(base_a,base_b,s));}}
 let mut a=vec![();7];let mut b=vec![();7];chunks2(&mut a,&mut b);
 println!("usize lengths 0..257, 64 offset pairs, three methods, repeated batch states and ZST passed");
}
fn main(){let args:Vec<_>=std::env::args().collect();let mode=&args[1];if mode=="check"{check();return}let reps:usize=args[2].parse().unwrap();let n:usize=args.get(3).map_or(30,|s|s.parse().unwrap());let ax:usize=args.get(4).map_or(0,|s|s.parse().unwrap());let ay:usize=args.get(5).map_or(0,|s|s.parse().unwrap());let mut x:Vec<_>=(0..n+ax+8).collect();let mut y:Vec<_>=(n+ax+8..2*(n+ax+8)+ay+8).collect();let mut skip=0;
 let now=std::time::Instant::now();if mode.starts_with("leaf_"){let f:fn(&mut[usize],&mut[usize])=match mode.as_str(){"leaf_std"=>leaf_std,"leaf_chunk"=>leaf_chunk,"leaf_vec"=>leaf_vec,_=>leaf_scalar};for _ in 0..reps{f(&mut x[ax..ax+n],&mut y[ay..ay+n]);}}else{let a:&mut[usize;30]=(&mut x[ax..ax+30]).try_into().unwrap();let b:&mut[usize;30]=(&mut y[ay..ay+30]).try_into().unwrap();let f:fn(&mut[usize;30],&mut[usize;30],&mut usize)->(usize,usize)=match mode.as_str(){"original"=>original,"chunk"=>chunk_batch,"vec"=>vec_batch,"scalar"=>scalar_batch,"reg"=>reg_batch,"even"=>even_batch,_=>panic!("mode")};for _ in 0..reps{black_box(f(a,b,&mut skip));}}
 let elapsed=now.elapsed().as_nanos();black_box((&x,&y,skip));println!("{{\"elapsed_ns\":{},\"reps\":{},\"x_mod64\":{},\"y_mod64\":{}}}",elapsed,reps,(x.as_ptr()as usize+ax*8)%64,(y.as_ptr()as usize+ay*8)%64);
}
